changeSet.sql:
DECLARE
    v_user_id      usuario.user_id%TYPE;
    v_rol_creado   BOOLEAN := FALSE;
    v_n            NUMBER;
    v_filas        NUMBER;
    v_mas_antigua  NUMBER;
BEGIN
    -- El DDL se aplica antes que las semillas DML, asi que cat_rol puede estar vacio:
    -- el oraculo se procura el rol que necesita y lo retira si fue el quien lo creo.
    SELECT COUNT(*) INTO v_n FROM cat_rol WHERE role_code = 'EMPLEADO';
    IF v_n = 0 THEN
        INSERT INTO cat_rol (role_code, role_name, display_order, is_active)
        VALUES ('EMPLEADO', 'Empleado (oraculo TSK-049)', 9049, 'Y');
        v_rol_creado := TRUE;
    END IF;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, password_hash, password_algorithm)
    VALUES ('Oraculo Historico TSK-049', 'oraculo.tsk049.historico@mind.local',
            'oraculo.tsk049.historico@mind.local', 'EMPLEADO',
            'hash-oraculo-0', 'argon2id')
    RETURNING user_id INTO v_user_id;

    -- Cuatro contrasenias sucesivas: la mas antigua debe caer al insertarse la cuarta.
    INSERT INTO usuario_password_historico (user_id, password_hash, created_at)
    VALUES (v_user_id, 'hash-oraculo-1', SYS_EXTRACT_UTC(SYSTIMESTAMP) - INTERVAL '3' HOUR);
    INSERT INTO usuario_password_historico (user_id, password_hash, created_at)
    VALUES (v_user_id, 'hash-oraculo-2', SYS_EXTRACT_UTC(SYSTIMESTAMP) - INTERVAL '2' HOUR);
    INSERT INTO usuario_password_historico (user_id, password_hash, created_at)
    VALUES (v_user_id, 'hash-oraculo-3', SYS_EXTRACT_UTC(SYSTIMESTAMP) - INTERVAL '1' HOUR);
    INSERT INTO usuario_password_historico (user_id, password_hash, created_at)
    VALUES (v_user_id, 'hash-oraculo-4', SYS_EXTRACT_UTC(SYSTIMESTAMP));

    SELECT COUNT(*) INTO v_filas
      FROM usuario_password_historico WHERE user_id = v_user_id;
    SELECT COUNT(*) INTO v_mas_antigua
      FROM usuario_password_historico WHERE user_id = v_user_id AND password_hash = 'hash-oraculo-1';

    DELETE FROM usuario_password_historico WHERE user_id = v_user_id;
    DELETE FROM usuario WHERE user_id = v_user_id;
    IF v_rol_creado THEN
        DELETE FROM cat_rol WHERE role_code = 'EMPLEADO';
    END IF;

    IF v_filas <> 3 THEN
        RAISE_APPLICATION_ERROR(-20069,
            'REQ-069: tras cuatro contrasenias el historico conserva ' || v_filas || ' filas en lugar de 3');
    END IF;
    IF v_mas_antigua <> 0 THEN
        RAISE_APPLICATION_ERROR(-20069,
            'REQ-069: la contrasenia mas antigua sigue en el historico tras la cuarta');
    END IF;
END;
